def load(path: Union[os.PathLike, str]) -> c.CDLL:
    """Load exactly the caller-selected shared library and declare every symbol."""
    library = c.CDLL(os.fspath(path))

    def declare(name: str, arguments: list[object], result: object) -> None:
        function = getattr(library, name)
        function.argtypes = arguments
        function.restype = result

    declare("mimhid_last_error", [], c.POINTER(ErrorDetail))
    declare("mimhid_result_name", [c.c_int32], c.c_char_p)
    declare("mimhid_frame_type_name", [c.c_int32], c.c_char_p)
    declare("mimhid_version", [], c.c_uint32)
    declare("mimhid_discover", [c.c_uint32, c.POINTER(DiscoveryP)], c.c_int32)
    declare("mimhid_discovery_count", [DiscoveryP], c.c_size_t)
    declare("mimhid_discovery_get", [DiscoveryP, c.c_size_t], c.POINTER(DeviceInfo))
    declare("mimhid_discovery_destroy", [DiscoveryP], None)
    declare("mimhid_device_open", [c.c_char_p, c.POINTER(DeviceConfig), c.POINTER(DeviceP)], c.c_int32)
    declare("mimhid_device_close", [DeviceP, c.c_uint32, c.c_uint32], c.c_int32)
    declare("mimhid_device_set_usb_identity", [DeviceP, c.POINTER(UsbDevice), c.POINTER(UsbConfig), c.POINTER(CommitTimeouts)], c.c_int32)
    declare("mimhid_device_latched_error", [DeviceP], c.c_int32)
    declare("mimhid_device_is_ready", [DeviceP], c.c_int32)
    declare("mimhid_device_wait_ready", [DeviceP, c.c_uint32], c.c_int32)
    declare("mimhid_device_batch_begin", [DeviceP], c.c_int32)
    declare("mimhid_device_batch_end", [DeviceP, c.POINTER(CommitTimeouts)], c.c_int32)
